/**
 * Bulk-import persistence: the per-workspace ledger of finished imports and the one transaction that writes a whole batch.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, count, eq, inArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImports,
  issueLabels,
  issues,
  labels,
  members,
  users,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { brandId } from "./_mappers";
import { compact } from "./_paging";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type { Db } from "@/server/db";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";

type Tx = Parameters<Parameters<Db["transaction"]>[0]>[0];

export interface RecordedImport {
  readonly projectId: ProjectId;
  /** In file order. */
  readonly issueIds: readonly IssueId[];
}

export interface ImportBatch {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportIssueRowInput[];
  /**
   * Called inside the transaction with the project's live issue count, after
   * the replay check and before any write. Throw to refuse the batch.
   */
  readonly assertRoom: (liveIssues: number) => void;
}

export interface ImportWrite extends RecordedImport {
  /** True when the key was already recorded, so nothing was written. */
  readonly replayed: boolean;
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<RecordedImport | null> {
  return readImport(getDb(), orgId, importKey);
}

/**
 * Writes every row of the batch, the labels it needs and the ledger entry in a
 * single transaction, so a failure anywhere leaves nothing behind. Everything
 * between `BEGIN` and `COMMIT` is synchronous, which is what keeps the number
 * allocation and the replay check free of interleaving writers.
 */
export async function insertImport(batch: ImportBatch): Promise<ImportWrite> {
  const { orgId, projectId, importKey, authorId, rows } = batch;

  return getDb().transaction((tx) => {
    const prior = readImport(tx, orgId, importKey);
    if (prior) return { ...prior, replayed: true };

    const liveIssues =
      tx
        .select({ value: count() })
        .from(issues)
        .where(
          and(
            ...compact(
              orgPredicate(issues.orgId, orgId),
              eq(issues.projectId, projectId),
              livePredicate(issues.archivedAt, {}),
            ),
          ),
        )
        .get()?.value ?? 0;
    batch.assertRoom(liveIssues);

    const stamp = toIsoTimestamp(new Date());
    const assignees = rows.some((row) => row.assigneeEmail)
      ? activeMemberIdsByEmail(tx, orgId)
      : new Map<string, UserId>();
    const labelIds = resolveLabelIds(tx, orgId, stamp, rows);

    // Archived issues keep their number, so the max is over every row.
    let number =
      tx
        .select({ value: sql<number | null>`max(${issues.number})` })
        .from(issues)
        .where(
          and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
        )
        .get()?.value ?? 0;

    // Ids sort by creation time; sorting the batch's ids makes id order agree
    // with file order even for rows minted in the same millisecond.
    const issueIds = rows.map(() => brandId<IssueId>(newId())).sort();

    rows.forEach((row, index) => {
      const issueId = issueIds[index] as IssueId;
      number += 1;

      tx.insert(issues)
        .values({
          id: issueId,
          orgId,
          projectId,
          number,
          title: row.title,
          description: row.description ?? null,
          status: row.status ?? "backlog",
          priority: row.priority ?? "none",
          authorId,
          assigneeId: row.assigneeEmail
            ? (assignees.get(row.assigneeEmail.toLowerCase()) ?? null)
            : null,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt ?? null,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      const rowLabelIds = [...new Set(row.labels ?? [])].flatMap((name) => {
        const id = labelIds.get(name);
        return id === undefined ? [] : [id];
      });
      if (rowLabelIds.length > 0) {
        tx.insert(issueLabels)
          .values(rowLabelIds.map((labelId) => ({ orgId, issueId, labelId })))
          .run();
      }
    });

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId,
        projectId,
        importKey,
        issueIds: JSON.stringify(issueIds),
        importedBy: authorId,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { projectId, issueIds, replayed: false };
  });
}

function readImport(
  db: Db | Tx,
  orgId: OrgId,
  importKey: string,
): RecordedImport | null {
  const row = db
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
