  const byName = new Map<string, LabelId>();
  if (wanted.length === 0) return byName;

  const existing = tx
    .select({ id: labels.id, name: labels.name })
    .from(labels)
    .where(
      and(orgPredicate(labels.orgId, orgId), inArray(labels.name, wanted)),
    )
    .all();
  for (const label of existing) byName.set(label.name, brandId<LabelId>(label.id));

  for (const name of wanted) {
    if (byName.has(name)) continue;
    const created = tx
      .insert(labels)
      .values({ id: newId(), orgId, name, createdAt: stamp, updatedAt: stamp })
      .returning({ id: labels.id })
      .get();
