  actor: Actor,''','''/**
 * Bulk import: every row becomes an issue in file order, or none does. The
 * gates are createIssue's — scope, live project, `issue:create` — and are
 * followed by the replay check (a key this workspace already imported returns
 * that import untouched), the plan quota for the whole batch and the workspace's
 * issue-creation allowance, one unit per row. All of that is settled before the
 * batch is written in one transaction, so a refused import writes nothing and
 * leaves its key unused. One `issues.imported` event announces the batch; no
 * per-issue events fire, so nobody is notified and no webhook is queued.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const replay = async (recorded: importRepo.RecordedImport) => {
    if (recorded.projectId !== project.id) {
      // The key was spent on another project; its issues are only shown to
      // someone who may read that project.
      const original = requireFound(
        await projectRepo.findProjectById(input.orgId, recorded.projectId),
        "Project",
        recorded.projectId,
      );
      assertCan(actor, "issue:read", projectResource(original));
    }

    return {
      importKey: input.importKey,
      projectId: recorded.projectId,
      issues: await issueRepo.listIssuesByIds(input.orgId, recorded.issueIds),
      replayed: true,
    };
  };

  const previous = await importRepo.findImport(input.orgId, input.importKey);
  if (previous) return replay(previous);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const requested = input.rows.length;
  const assertRoom = (used: number) =>
    assertIssueRoom(org.plan, project.key, used, requested);

  assertRoom(await issueRepo.countIssues(input.orgId, input.projectId));

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    requested,
    org.plan,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const written = await importRepo.insertImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows,
    assertRoom,
  });
  // Another upload of the same key won the race between the check and the write.
  if (written.replayed) return replay(written);

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: written.issueIds,
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues: await issueRepo.listIssuesByIds(input.orgId, written.issueIds),
    replayed: false,
  };
}

