/**
 * Bulk issue import: gates, all-or-nothing quota and rate refusal, numbering,
 * assignee and label resolution, replays and the single batch announcement.
 *
 * The real event handlers are attached the way the server does at start-up, so
 * the search, usage, audit, notification and webhook reactions are the real ones.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { resetEventBus, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { importIssuesSchema } from "@/schemas/issue-import";
import { getDb, issues, labels, notifications, webhookDeliveries } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookService from "@/server/services/webhook-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ImportIssuesInput } from "@/schemas/issue-import";
import type { OrgId, ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let keyCounter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
  unregisterEventHandlers();
  resetEventBus();
  registerEventHandlers();
});

function freshKey(): string {
  keyCounter += 1;
  return `import-key-${keyCounter}`;
}

/** A parsed upload, so schema defaults are applied the way the client path does. */
function upload(
  tenant: Tenant,
  rows: readonly Record<string, unknown>[],
  overrides: { importKey?: string; projectId?: ProjectId; orgId?: OrgId } = {},
): ImportIssuesInput {
  return importIssuesSchema.parse({
    orgId: overrides.orgId ?? tenant.org.id,
    projectId: overrides.projectId ?? tenant.project.id,
    importKey: overrides.importKey ?? freshKey(),
    rows,
  });
}

function titled(count: number, prefix = "Row"): Record<string, unknown>[] {
  return Array.from({ length: count }, (_, i) => ({ title: `${prefix} ${i + 1}` }));
}

function capture<K extends TaskflowEventType>(type: K, into: Unsubscribe[]) {
  const seen: TaskflowEventMap[K][] = [];
  into.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

function issueCount(orgId: OrgId): number {
  return getDb().select().from(issues).all().filter((row) => row.orgId === orgId).length;
}

describe("importIssues — rows", () => {
  it("creates every row in file order, numbered after the highest number ever used", async () => {
    const tenant = await createTenant("imp-rows");
    for (let n = 1; n <= 3; n += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `Seed ${n}` }),
        tenant.userIds.member,
        n,
      );
    }
    const seeded = await issueRepo.findIssueByNumber(tenant.org.id, tenant.project.id, 3);
    await issueRepo.archiveIssue(tenant.org.id, seeded!.id);

    const result = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [
        {
          title: "First",
          description: "details",
          status: "in_progress",
          priority: "high",
          dueAt: "2026-06-01T00:00:00.000Z",
        },
        { title: "Second" },
        { title: "Third", status: "done", priority: "urgent" },
      ]),
    );

    expect(result.replayed).toBe(false);
    expect(result.projectId).toBe(tenant.project.id);
    expect(result.issues.map((i) => [i.number, i.title])).toEqual([
      [4, "First"],
      [5, "Second"],
      [6, "Third"],
    ]);
    expect(result.issues[0]).toMatchObject({
      description: "details",
      status: "in_progress",
      priority: "high",
      dueAt: "2026-06-01T00:00:00.000Z",
      authorId: tenant.userIds.member,
      assigneeId: null,
      parentId: null,
      estimate: null,
      archivedAt: null,
    });
    expect(result.issues[1]).toMatchObject({ status: "backlog", priority: "none", description: null });

    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the import" }),
    );
    expect(next.number).toBe(7);
  });
});

describe("importIssues — access", () => {
  it("refuses with the create-issue errors and writes nothing", async () => {
    const tenant = await createTenant("imp-access");
    const other = await createTenant("imp-access-other");
    const before = issueCount(tenant.org.id);

    await expect(
      issueService.importIssues(tenant.actors.viewer, upload(tenant, titled(2))),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.importIssues(tenant.actors.member, upload(other, titled(2))),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        upload(tenant, titled(2), { projectId: "01HZZZZZZZZZZZZZZZZZZZZZZZ" as ProjectId }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        upload(tenant, titled(2), { projectId: other.project.id }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await projectRepo.archiveProject(tenant.org.id, tenant.project.id);
    await expect(
      issueService.importIssues(tenant.actors.member, upload(tenant, titled(2))),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect(issueCount(tenant.org.id)).toBe(before);
    expect(issueCount(other.org.id)).toBe(0);
  });
});

describe("importIssues — all or nothing", () => {
  it("refuses a batch that would pass the plan quota, the same way a single create does", async () => {
    const tenant = await createTenant("imp-quota", "free");
    for (let n = 1; n <= 50; n += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `Seed ${n}` }),
        tenant.userIds.member,
        n,
      );
    }
    const key = freshKey();

    await expect(
      issueService.importIssues(tenant.actors.member, upload(tenant, titled(51), { importKey: key })),
    ).rejects.toThrow(/allows no more issues/);
    expect(issueCount(tenant.org.id)).toBe(50);

    // The refusal did not use up the key, and exactly filling the quota is fine.
    const result = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, titled(50), { importKey: key }),
    );
    expect(result.replayed).toBe(false);
    expect(result.issues).toHaveLength(50);
    expect(issueCount(tenant.org.id)).toBe(100);
  });

  it("counts issues the way a single create does: archived ones make room", async () => {
    const tenant = await createTenant("imp-quota-live", "free");
    for (let n = 1; n <= 100; n += 1) {
      const issue = await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `Seed ${n}` }),
        tenant.userIds.member,
        n,
      );
      if (n <= 10) await issueRepo.archiveIssue(tenant.org.id, issue.id);
    }

    const result = await issueService.importIssues(tenant.actors.member, upload(tenant, titled(10)));
    expect(result.issues.map((i) => i.number)).toEqual([101, 102, 103, 104, 105, 106, 107, 108, 109, 110]);
  });

  it("refuses when the creation allowance does not cover the batch, and keeps the key", async () => {
    const tenant = await createTenant("imp-rate", "free");
    const key = freshKey();

    // The free plan's allowance is 60 units; 61 rows fit the quota but not the bucket.
    await expect(
      issueService.importIssues(tenant.actors.member, upload(tenant, titled(61), { importKey: key })),
    ).rejects.toThrow(/rate limit/i);
    expect(issueCount(tenant.org.id)).toBe(0);

    const result = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, titled(60), { importKey: key }),
    );
    expect(result.replayed).toBe(false);

    // One unit was spent per row, so the bucket is now empty.
    await expect(
      issueService.importIssues(tenant.actors.member, upload(tenant, titled(2))),
    ).rejects.toThrow(/rate limit/i);
  });

  it("sizes the allowance for the workspace's plan", async () => {
    const tenant = await createTenant("imp-rate-growth", "growth");
    const result = await issueService.importIssues(tenant.actors.member, upload(tenant, titled(200)));
    expect(result.issues).toHaveLength(200);
  });

  it("leaves nothing behind when the batch fails part-way", async () => {
    const tenant = await createTenant("imp-atomic");
    const original = usageRepo.getUsage;
    expect(original).toBeDefined();

    // A label name that collides with nothing, then an over-long title the
    // database itself would accept: force the failure with a bad due date type.
    const bad = upload(tenant, [
      { title: "Fine", labels: ["Ghost"] },
      { title: "Also fine", labels: ["Ghost"] },
    ]);
    (bad.rows[1] as { title: unknown }).title = { not: "a string" };

    await expect(issueService.importIssues(tenant.actors.member, bad)).rejects.toThrow();
    expect(issueCount(tenant.org.id)).toBe(0);
    expect(await labelRepo.listLabels(tenant.org.id)).toHaveLength(0);

    const key = bad.importKey;
    const ok = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [{ title: "Recovered" }], { importKey: key }),
    );
    expect(ok.replayed).toBe(false);
  });
});

describe("importIssues — assignees", () => {
  it("matches active members case-insensitively and leaves everyone else unassigned", async () => {
    const tenant = await createTenant("imp-assign");
    const outsider = await userRepo.insertUser({
      email: "outsider@elsewhere.test",
      name: "Outsider",
      passwordHash: "seed",
    });
    const leaver = await userRepo.insertUser({
      email: "leaver@imp-assign.test",
      name: "Leaver",
      passwordHash: "seed",
    });
    const leaverMember = await memberRepo.insertMember(tenant.org.id, leaver.id, "member", null);
    await memberRepo.archiveMember(tenant.org.id, leaverMember.id);

    const result = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [
        { title: "Known", assigneeEmail: "Admin@IMP-ASSIGN.test" },
        { title: "Unknown", assigneeEmail: "nobody@imp-assign.test" },
        { title: "Outsider", assigneeEmail: outsider.email },
        { title: "Removed", assigneeEmail: leaver.email },
        { title: "None" },
      ]),
    );

    expect(result.issues.map((i) => i.assigneeId)).toEqual([
      tenant.userIds.admin,
      null,
      null,
      null,
      null,
    ]);
  });
});

describe("importIssues — labels", () => {
  it("matches names exactly within the workspace and creates missing ones once", async () => {
    const tenant = await createTenant("imp-labels");
    const other = await createTenant("imp-labels-other");
    const existing = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "bug",
      color: "#ff0000",
      description: "kept",
    });
    const foreign = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "urgent",
      color: "#00ff00",
      description: null,
    });

    const result = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [
        { title: "One", labels: ["bug", "urgent", "urgent"] },
        { title: "Two", labels: ["urgent", "Bug"] },
        { title: "Three" },
      ]),
    );

    const mine = await labelRepo.listLabels(tenant.org.id);
    expect(mine.map((l) => l.name).sort()).toEqual(["Bug", "bug", "urgent"]);
    const urgent = mine.find((l) => l.name === "urgent")!;
    const capitalised = mine.find((l) => l.name === "Bug")!;
    expect(urgent.id).not.toBe(foreign.id);
    expect(urgent).toMatchObject({ color: "#94a3b8", description: null });
    expect(capitalised).toMatchObject({ color: "#94a3b8", description: null });
    expect(mine.find((l) => l.name === "bug")).toMatchObject({ id: existing.id, color: "#ff0000", description: "kept" });

    const [one, two, three] = result.issues;
    expect([...one!.labelIds].sort()).toEqual([existing.id, urgent.id].sort());
    expect([...two!.labelIds].sort()).toEqual([capitalised.id, urgent.id].sort());
    expect(three!.labelIds).toEqual([]);

    expect(await labelRepo.listLabels(other.org.id)).toHaveLength(1);
    expect(getDb().select().from(labels).all()).toHaveLength(
      (await labelRepo.listLabels(tenant.org.id)).length + 1 + (await labelRepo.listLabels(other.org.id)).length - 1,
    );
  });
});

describe("importIssues — replays", () => {
  it("returns the first import for a repeated key and creates nothing", async () => {
    const tenant = await createTenant("imp-replay");
    const key = freshKey();
    const first = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [{ title: "Alpha", labels: ["x", "y"] }, { title: "Beta" }], { importKey: key }),
    );

    const again = await issueService.importIssues(
      tenant.actors.admin,
      upload(tenant, titled(5, "Different"), { importKey: key }),
    );

    expect(again.replayed).toBe(true);
    expect(again.importKey).toBe(key);
    expect(again.projectId).toBe(tenant.project.id);
    expect(again.issues).toEqual(first.issues);
    expect(issueCount(tenant.org.id)).toBe(2);

    const fresh = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [{ title: "Alpha" }, { title: "Beta" }]),
    );
    expect(fresh.replayed).toBe(false);
    expect(fresh.issues.map((i) => i.number)).toEqual([3, 4]);
  });

  it("scopes keys to the workspace", async () => {
    const one = await createTenant("imp-keys-one");
    const two = await createTenant("imp-keys-two");
    const key = freshKey();

    await issueService.importIssues(one.actors.member, upload(one, titled(1), { importKey: key }));
    const result = await issueService.importIssues(two.actors.member, upload(two, titled(2), { importKey: key }));

    expect(result.replayed).toBe(false);
    expect(result.issues).toHaveLength(2);
  });

  it("does not spend allowance, quota or events on a replay", async () => {
    const tenant = await createTenant("imp-replay-free", "free");
    const key = freshKey();
    await issueService.importIssues(tenant.actors.member, upload(tenant, titled(60), { importKey: key }));

    const seen: Unsubscribe[] = [];
    const imported = capture("issues.imported", seen);
    const replay = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, titled(500), { importKey: key }),
    );
    seen.forEach((off) => off());

    expect(replay.replayed).toBe(true);
    expect(replay.issues).toHaveLength(60);
    expect(imported).toHaveLength(0);
  });
});

describe("importIssues — announcements", () => {
  it("publishes one batch event and every reaction follows from it", async () => {
    const tenant = await createTenant("imp-events", "growth");
    await webhookService.createWebhook(tenant.actors.admin, {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/taskflow",
      eventTypes: ["issue.created", "issue.assigned", "issue.updated"],
    });
    await usageRepo.recomputeUsage(tenant.org.id);

    const offs: Unsubscribe[] = [];
    const imported = capture("issues.imported", offs);
    const created = capture("issue.created", offs);
    const assigned = capture("issue.assigned", offs);

    const result = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [
        { title: "Searchable zebra crossing", assigneeEmail: "admin@imp-events.test" },
        { title: "Second one", description: "mentions a quokka" },
      ], { importKey: "batch-key-1" }),
    );
    offs.forEach((off) => off());

    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
      importKey: "batch-key-1",
      issueIds: result.issues.map((i) => i.id),
    });

    // Searchable right away.
    const found = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "zebra",
      kinds: [],
      limit: 10,
    } as never);
    expect(found.items.map((row) => row.subjectId)).toEqual([result.issues[0]!.id]);
    const found2 = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "quokka",
      kinds: [],
      limit: 10,
    } as never);
    expect(found2.items.map((row) => row.subjectId)).toEqual([result.issues[1]!.id]);

    // Meter rises by the batch and agrees with a recount.
    const meter = await usageRepo.getUsage(tenant.org.id);
    expect(meter.issuesUsed).toBe(2);
    expect((await usageRepo.recomputeUsage(tenant.org.id)).issuesUsed).toBe(2);

    // Exactly one audit entry.
    const log = await activityRepo.listActivity({ orgId: tenant.org.id, limit: 50, cursor: null } as never);
    const rows = log.items.filter((event) => event.action === "issues.imported");
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "batch-key-1" },
    });
    expect(log.items.filter((event) => event.action === "issue.created")).toHaveLength(0);

    // Nobody hears about it, and no webhook is queued.
    expect(getDb().select().from(notifications).all()).toHaveLength(0);
    expect(getDb().select().from(webhookDeliveries).all()).toHaveLength(0);
  });

  it("publishes nothing for a refused import", async () => {
    const tenant = await createTenant("imp-events-refused");
    const offs: Unsubscribe[] = [];
    const imported = capture("issues.imported", offs);

    await expect(
      issueService.importIssues(tenant.actors.viewer, upload(tenant, titled(2))),
    ).rejects.toThrow();
    offs.forEach((off) => off());

    expect(imported).toHaveLength(0);
  });
});

describe("rate limiter", () => {
  it("keeps sizing other calls as before", async () => {
    const verdict = await consumeRateLimit("01HZZZAAAAAAAAAAAAAAAAAAAA" as OrgId, "member:invite");
    expect(verdict.remaining).toBe(19);
  });
});

