 * Bulk issue import: gates, all-or-nothing quota and rate refusal, numbering,
 * assignee and label resolution, replays and the single batch announcement.
 *
 * The real event handlers are attached the way the server does at start-up, so
 * the search, usage, audit, notification and webhook reactions are the real ones.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { resetEventBus, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { importIssuesSchema } from "@/schemas/issue-import";
import { getDb, issues, labels, notifications, webhookDeliveries } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
