import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookService from "@/server/services/webhook-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ImportIssuesInput } from "@/schemas/issue-import";
import type { OrgId, ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let keyCounter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
  unregisterEventHandlers();
  resetEventBus();
  registerEventHandlers();
});

function freshKey(): string {
  keyCounter += 1;
  return `import-key-${keyCounter}`;
}

/** A parsed upload, so schema defaults are applied the way the client path does. */
function upload(
  tenant: Tenant,
  rows: readonly Record<string, unknown>[],
  overrides: { importKey?: string; projectId?: ProjectId; orgId?: OrgId } = {},
): ImportIssuesInput {
  return importIssuesSchema.parse({
    orgId: overrides.orgId ?? tenant.org.id,
    projectId: overrides.projectId ?? tenant.project.id,
    importKey: overrides.importKey ?? freshKey(),
    rows,
  });
}

function titled(count: number, prefix = "Row"): Record<string, unknown>[] {
  return Array.from({ length: count }, (_, i) => ({ title: `${prefix} ${i + 1}` }));
}

function capture<K extends TaskflowEventType>(type: K, into: Unsubscribe[]) {
  const seen: TaskflowEventMap[K][] = [];
  into.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

function issueCount(orgId: OrgId): number {
  return getDb().select().from(issues).all().filter((row) => row.orgId === orgId).length;
}

