  it("creates every row in file order, numbered after the highest number ever used", async () => {
    const tenant = await createTenant("imp-rows");
    for (let n = 1; n <= 3; n += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `Seed ${n}` }),
        tenant.userIds.member,
        n,
      );
    }
    const seeded = await issueRepo.findIssueByNumber(tenant.org.id, tenant.project.id, 3);
    await issueRepo.archiveIssue(tenant.org.id, seeded!.id);

    const result = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [
        {
          title: "First",
          description: "details",
          status: "in_progress",
          priority: "high",
          dueAt: "2026-06-01T00:00:00.000Z",
        },
        { title: "Second" },
        { title: "Third", status: "done", priority: "urgent" },
      ]),
    );

    expect(result.replayed).toBe(false);
    expect(result.projectId).toBe(tenant.project.id);
    expect(result.issues.map((i) => [i.number, i.title])).toEqual([
      [4, "First"],
      [5, "Second"],
      [6, "Third"],
    ]);
    expect(result.issues[0]).toMatchObject({
      description: "details",
      status: "in_progress",
      priority: "high",
      dueAt: "2026-06-01T00:00:00.000Z",
      authorId: tenant.userIds.member,
      assigneeId: null,
      parentId: null,
      estimate: null,
      archivedAt: null,
    });
    expect(result.issues[1]).toMatchObject({ status: "backlog", priority: "none", description: null });

    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the import" }),
    );
    expect(next.number).toBe(7);
  });
});

