describe("importIssues — labels", () => {
  it("matches names exactly within the workspace and creates missing ones once", async () => {
    const tenant = await createTenant("imp-labels");
    const other = await createTenant("imp-labels-other");
    const existing = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "bug",
      color: "#ff0000",
      description: "kept",
    });
    const foreign = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "urgent",
      color: "#00ff00",
      description: null,
    });

    const result = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [
        { title: "One", labels: ["bug", "urgent", "urgent"] },
        { title: "Two", labels: ["urgent", "Bug"] },
        { title: "Three" },
      ]),
    );

    const mine = await labelRepo.listLabels(tenant.org.id);
    expect(mine.map((l) => l.name).sort()).toEqual(["Bug", "bug", "urgent"]);
    const urgent = mine.find((l) => l.name === "urgent")!;
    const capitalised = mine.find((l) => l.name === "Bug")!;
    expect(urgent.id).not.toBe(foreign.id);
    expect(urgent).toMatchObject({ color: "#94a3b8", description: null });
    expect(capitalised).toMatchObject({ color: "#94a3b8", description: null });
    expect(mine.find((l) => l.name === "bug")).toMatchObject({ id: existing.id, color: "#ff0000", description: "kept" });

    const [one, two, three] = result.issues;
    expect([...one!.labelIds].sort()).toEqual([existing.id, urgent.id].sort());
    expect([...two!.labelIds].sort()).toEqual([capitalised.id, urgent.id].sort());
    expect(three!.labelIds).toEqual([]);

    expect(await labelRepo.listLabels(other.org.id)).toHaveLength(1);
    expect(getDb().select().from(labels).all()).toHaveLength(
      (await labelRepo.listLabels(tenant.org.id)).length + 1 + (await labelRepo.listLabels(other.org.id)).length - 1,
    );
  });
});

describe("importIssues — replays", () => {
  it("returns the first import for a repeated key and creates nothing", async () => {
    const tenant = await createTenant("imp-replay");
    const key = freshKey();
    const first = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [{ title: "Alpha", labels: ["x", "y"] }, { title: "Beta" }], { importKey: key }),
    );

    const again = await issueService.importIssues(
      tenant.actors.admin,
      upload(tenant, titled(5, "Different"), { importKey: key }),
    );

    expect(again.replayed).toBe(true);
    expect(again.importKey).toBe(key);
    expect(again.projectId).toBe(tenant.project.id);
    expect(again.issues).toEqual(first.issues);
    expect(issueCount(tenant.org.id)).toBe(2);

    const fresh = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [{ title: "Alpha" }, { title: "Beta" }]),
    );
    expect(fresh.replayed).toBe(false);
    expect(fresh.issues.map((i) => i.number)).toEqual([3, 4]);
  });

  it("scopes keys to the workspace", async () => {
    const one = await createTenant("imp-keys-one");
    const two = await createTenant("imp-keys-two");
    const key = freshKey();

    await issueService.importIssues(one.actors.member, upload(one, titled(1), { importKey: key }));
    const result = await issueService.importIssues(two.actors.member, upload(two, titled(2), { importKey: key }));

    expect(result.replayed).toBe(false);
    expect(result.issues).toHaveLength(2);
  });

  it("does not spend allowance, quota or events on a replay", async () => {
    const tenant = await createTenant("imp-replay-free", "free");
    const key = freshKey();
    await issueService.importIssues(tenant.actors.member, upload(tenant, titled(60), { importKey: key }));

    const seen: Unsubscribe[] = [];
    const imported = capture("issues.imported", seen);
    const replay = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, titled(500), { importKey: key }),
    );
    seen.forEach((off) => off());

    expect(replay.replayed).toBe(true);
    expect(replay.issues).toHaveLength(60);
    expect(imported).toHaveLength(0);
  });
});

describe("importIssues — announcements", () => {
  it("publishes one batch event and every reaction follows from it", async () => {
    const tenant = await createTenant("imp-events", "growth");
    await webhookService.createWebhook(tenant.actors.admin, {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/taskflow",
      eventTypes: ["issue.created", "issue.assigned", "issue.updated"],
    });
    await usageRepo.recomputeUsage(tenant.org.id);

    const offs: Unsubscribe[] = [];
    const imported = capture("issues.imported", offs);
    const created = capture("issue.created", offs);
    const assigned = capture("issue.assigned", offs);

    const result = await issueService.importIssues(
      tenant.actors.member,
      upload(tenant, [
        { title: "Searchable zebra crossing", assigneeEmail: "admin@imp-events.test" },
        { title: "Second one", description: "mentions a quokka" },
      ], { importKey: "batch-key-1" }),
    );
    offs.forEach((off) => off());

    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
      importKey: "batch-key-1",
      issueIds: result.issues.map((i) => i.id),
    });

    // Searchable right away.
    const found = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "zebra",
      kinds: [],
      limit: 10,
    } as never);
    expect(found.items.map((row) => row.subjectId)).toEqual([result.issues[0]!.id]);
    const found2 = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "quokka",
      kinds: [],
      limit: 10,
    } as never);
    expect(found2.items.map((row) => row.subjectId)).toEqual([result.issues[1]!.id]);

    // Meter rises by the batch and agrees with a recount.
    const meter = await usageRepo.getUsage(tenant.org.id);
    expect(meter.issuesUsed).toBe(2);
    expect((await usageRepo.recomputeUsage(tenant.org.id)).issuesUsed).toBe(2);

    // Exactly one audit entry.
    const log = await activityRepo.listActivity({ orgId: tenant.org.id, limit: 50, cursor: null } as never);
    const rows = log.items.filter((event) => event.action === "issues.imported");
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "batch-key-1" },
    });
    expect(log.items.filter((event) => event.action === "issue.created")).toHaveLength(0);

    // Nobody hears about it, and no webhook is queued.
    expect(getDb().select().from(notifications).all()).toHaveLength(0);
    expect(getDb().select().from(webhookDeliveries).all()).toHaveLength(0);
  });

  it("publishes nothing for a refused import", async () => {
    const tenant = await createTenant("imp-events-refused");
    const offs: Unsubscribe[] = [];
    const imported = capture("issues.imported", offs);

    await expect(
      issueService.importIssues(tenant.actors.viewer, upload(tenant, titled(2))),
    ).rejects.toThrow();
    offs.forEach((off) => off());

    expect(imported).toHaveLength(0);
  });
});

